use crate::aap::caps::kb_read;

struct Node;

/// Upper bound from the node's `ensures` clause, counted in characters.
const MAX_QUESTION_CHARS: usize = 512;

/// Truncate to at most `max` characters. Operates on char boundaries, so it
/// never panics on multi-byte input.
fn bounded(s: &str, max: usize) -> String {
    s.chars().take(max).collect()
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        // `requires` guarantees the input is already within the bound; the
        // truncation enforces `ensures len(question) <= 512` independently of
        // that precondition.
        let question = bounded(&query.query.question, MAX_QUESTION_CHARS);

        // The only capability this node holds is the read-only knowledge-base
        // lookup. A WIT list is always present, so `present(knowledge)` is
        // satisfied by the returned list; the lookup result is passed through
        // unmodified.
        let knowledge = kb_read::lookup(&question);

        ConversationContext {
            intent: query.query.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
